<?php require_once __DIR__.'/../inc/functions.php';require_login();$id=max(0,(int)($_GET['id']??0));$q=db()->prepare('SELECT * FROM students WHERE id=?');$q->execute([$id]);$student=$q->fetch();if(!$student){flash('error','الطالب غير موجود.');redirect('/students/index.php');}$v=['name'=>$student['name'],'email'=>$student['email'],'phone'=>$student['phone'],'address'=>$student['address']];$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($v as $k=>$x)$v[$k]=trim($_POST[$k]??'');if($v['name']===''||mb_strlen($v['name'])>100)$errors[]='الاسم مطلوب وبحد أقصى 100 محرف.';if(!valid_email($v['email'])||mb_strlen($v['email'])>100)$errors[]='البريد الإلكتروني غير صحيح.';if($v['phone']===''||mb_strlen($v['phone'])>15)$errors[]='الهاتف مطلوب وبحد أقصى 15 محرفاً.';if($v['address']==='')$errors[]='العنوان مطلوب.';if(!$errors){$newPic=$student['profile_picture'];try{$uploaded=upload_picture($_FILES['profile_picture']??[]);if($uploaded)$newPic=$uploaded;$q=db()->prepare('UPDATE students SET name=?,email=?,phone=?,address=?,profile_picture=? WHERE id=?');$q->execute([$v['name'],$v['email'],$v['phone'],$v['address'],$newPic,$id]);if($uploaded)delete_picture($student['profile_picture']);flash('success','تم تحديث بيانات الطالب.');redirect('/students/index.php');}catch(Throwable $ex){if(isset($uploaded)&&$uploaded)delete_picture($uploaded);$errors[]=$ex instanceof PDOException&&$ex->getCode()==='23000'?'البريد الإلكتروني مستخدم لطالب آخر.':$ex->getMessage();}}}$title='تعديل طالب';require __DIR__.'/../inc/header.php';require __DIR__.'/form.php';require __DIR__.'/../inc/footer.php';